public class Main {
    enum Color { RED, GREEN, BLUE }

    static String describe(Color color) {
        switch (color) {
            case RED: return "warm";
            case GREEN: return "natural";
            default: return "cool";
        }
    }

    public static void main(String[] args) {
        System.out.println(describe(Color.RED));
        System.out.println(describe(Color.GREEN));
        System.out.println(describe(Color.BLUE));
    }
}
